#!/usr/bin/env python3
"""Pin Phoenix Strike source rows and explicitly list the remaining port gates."""
import argparse,csv,hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];STAGE=ROOT/'.local/class-skills'
def build(check=False):
 source=ROOT/'tools/reference/d2r-named-equipment';manifest=json.loads((source/'sources.json').read_text());pins={};data={}
 for name in ['skills','missiles']:
  raw=(source/'json'/f'{name}.json').read_bytes();pins[name]=hashlib.sha256(raw).hexdigest();assert pins[name]==manifest['files'][f'json/{name}.json']['sha256'];data[name]=json.loads(raw)
 skill=data['skills']['280'];rows={k:v for k,v in data['missiles'].items() if k.startswith('royalstrike')};assert len(rows)==7
 assert skill['srvstfunc']==23 and skill['srvdofunc']==34 and [skill['srvprgfunc'+str(i)] for i in [1,2,3]]==[40,143,41] and not skill.get('prgstack',0) and not skill.get('prgdam',0)
 tree=json.loads((STAGE/'d2moo-source-tree.json').read_text());rel='source/D2Game/src/SKILLS/SkillAss.cpp';raw=(STAGE/'d2moo-pinned-source'/rel).read_bytes();assert hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==next(x['sha'] for x in tree['tree'] if x['path']==rel);text=raw.decode();blocks={}
 for name in ['SKILLS_SrvDo034_TigerStrike_CobraStrike_RoyalStrike','SKILLS_SrvDo040_RoyalStrike_ProgressiveFn1','SKILLS_SrvDo143_FistsOfFire_RoyalStrike_ProgressiveFn','sub_6FCF6D70','sub_6FCF7390','SKILLS_SrvDo041_RoyalStrike_ProgressiveFn3','sub_6FCF77E0']:
  m=re.search(r'^.*\b'+name+r'\([^;\n]*\)\s*\n\{',text,re.M);assert m,name;i=text.index('{',m.start())+1;depth=1
  while depth:depth+=(text[i]=='{')-(text[i]=='}');i+=1
  blocks[name]=hashlib.sha256(text[m.start():i].encode()).hexdigest()
 identity=next(x for x in json.loads((ROOT/'data/Sanctuary/Balance/class-skills.json').read_text()) if x['sourceId']==280)
 local=ROOT/'.local/research/d2r-3.3.93847/skills.txt';localRaw=local.read_bytes();actual=next(x for x in csv.DictReader(localRaw.decode().splitlines(),delimiter='\t') if x['skill']=='Royal Strike');keys=['srvstfunc','srvdofunc','srvprgfunc1','srvprgfunc2','srvprgfunc3','prgstack','prgdam','prgcalc2','prgcalc3','srvmissilea','srvmissileb','srvmissilec','auralencalc','aurastat1','aurastat2','aurastatcalc2','itypea1','anim','seqtrans','manashift','mana','lvlmana','AttackNoMana','leftskill','calc1']+['Param'+str(i) for i in range(1,8)]
 for key in keys:
  expect=skill.get(key,0);found=actual.get(key,'');assert (int(found or 0)==expect if isinstance(expect,int) else found==str(expect)),(key,expect,found)
 corroboration=dict(path=str(local.relative_to(ROOT)),sha256=hashlib.sha256(localRaw).hexdigest(),checkedFields={k:skill.get(k,0) for k in keys},missileRows='Current local seven-missile corroboration pending; cached pinned source hashes retained.')
 e=dict(referenceVersion='3.3.93847',talentId='assassin.phoenixstrike',sourceId=280,ability=identity['ability'],status='Source preparation only; no Phoenix Strike handler or native release enabled',installed=False,handlerEnabled=False,source=dict(cachedPinnedHashes=pins,skill=skill,missiles=rows,legacyCommit=tree['sha'],sourceHash=hashlib.sha256(raw).hexdigest(),reviewedRoutineHashes=blocks,localCascCorroboration=corroboration),established=['Current source280uses start23/do34,mele ancestry,A1,left/right input,4mana and AttackNoMana1; reuse the single-contact Tiger/Cobra builder rather than the dual-claw do35sequence.','Absent prgstack/prgdam mean only the selected charge tier callback runs; this is distinct from Fists/Thunder/Ice stacked releases. Existing ordinary consume-one remains separate from the legacy full-list removal.','Tier1callback40creates royalstrikemeteorcenter at the current target. Tier2callback143uses progressive step10and full sub6FCF6D70; tier3callback41emits16chaos-ice missiles with a private source RNG and saved target seed/vector. These are reviewed source facts,not a compiled Phoenix/native certificate.'],reuse=['Tiger/Cobra do34melee builder,once-paid resources/cancellation,independent charge families and ordinary successful consume-one.','Thunder full ring/LCG/initializer proof includes sub6FCF6D70and sub6FCF7390,but Phoenix selected missile/table parameters need their own composition.','Sorceress Meteor/fire ground,native saved projectiles,source missile packet/freeze states and shared fixed-point geometry are candidates for reuse after tracing Phoenix-specific routes.'],required=['Retain the current local32skill-field corroboration; corroborate seven missile rows,source ancestry and relevant A1 metadata.','Compile complete progressive tier selection,meteor center/falling/area/fire factory and clocks,lightning pattern/initializer/collision/child endpoints,and chaos-ice homing/velocity/damage2/freeze paths with current tables.','Phoenix uses nonstacked tier selection: do not release all elemental tiers or silently copy Thunder bolts/Ice cubes. Trace distinct two-tier versus multiple charged-family interaction.','Verify real weapon/gear/stored-live ranks/hard synergy/mastery,hit/block/miss/immunity,resource/fallback/lifecycle,real quick/both held/ordinary inputs,saved children/states and original-world smoke before installation.','Do not repeat martial-arts/Fury questions to the traps-only player; keep unsupported mechanics explicit and proceed with unaffected work.'],preparedComposition='tools/reference/phoenix-release-source-evidence.json',assets=dict(effects='Final Phoenix charge tiers,meteor warning/fall/explosion/fire,chain lightning,chaos ice/trail/freeze and audio remain pending; use identified native placeholders after implementation.',icons='Talent/left/right/quick icons remain in the separate240-row icon inventory.'),next='Compose current Phoenix source callbacks and numeric/factory/event routes before enabling its learned handler. No class completion certificate.')
 out=ROOT/'tools/reference/phoenix-strike-preflight.json';s=json.dumps(e,indent=2)+'\n'
 if check:assert out.read_text()==s,'Phoenix preflight stale'
 else:out.write_text(s)
 print('Phoenix Strike source preparation pinned;3callback tiers/7missile rows;no handler enabled.')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');build(p.parse_args().check)
